function summarizeWindow(events, nowMs, windowMs, cap) {
  const seen = new Set();
  const qualifying = [];

  for (const ev of events) {
    if (!ev) continue;

    // Dedupe raw events by non-empty string id, keeping the first occurrence
    // in input order. This happens BEFORE filtering, so a first occurrence
    // that is out-of-window or filtered still consumes the id.
    if (typeof ev.id === 'string' && ev.id.length > 0) {
      if (seen.has(ev.id)) continue;
      seen.add(ev.id);
    }

    if (typeof ev.ts !== 'number' || !Number.isFinite(ev.ts)) continue;
    if (ev.ts < nowMs - windowMs || ev.ts > nowMs) continue;
    if (ev.provider !== 'opencode-go') continue;
    if (ev.error) continue;
    if (typeof ev.model !== 'string') continue;
    if (ev.model.toLowerCase().endsWith('-free')) continue;

    qualifying.push(ev);
  }

  const used = qualifying.length;
  const remaining = Math.max(0, cap - used);
  const pct = Math.round((used / cap) * 1000) / 10;
  const overCap = used > cap;

  let minTs = Infinity;
  const counts = new Map();
  const prefix = 'opencode-go/';

  for (const ev of qualifying) {
    if (ev.ts < minTs) minTs = ev.ts;

    let name = ev.model.toLowerCase();
    if (name.startsWith(prefix)) name = name.slice(prefix.length);
    counts.set(name, (counts.get(name) || 0) + 1);
  }

  const oldestExpiresAt = used === 0 ? null : minTs + windowMs;

  const byModel = {};
  for (const key of Array.from(counts.keys()).sort()) {
    Object.defineProperty(byModel, key, {
      value: counts.get(key),
      enumerable: true,
      writable: true,
      configurable: true,
    });
  }

  return { used, remaining, pct, overCap, oldestExpiresAt, byModel };
}
